mapper.select:
select aaa.* from (
UNION ALL
) aaa left join SYS_DATADICT_LIST sdl on aaa.entrustStatus=sdl.ITEM_CODE and sdl.DICT_CODE='ENTRUST_STATUS' order by sdl.ORDER_NO, aaa.entrustId DESC

mapper.sql:
select ETR_ENTRUST.ENTRUST_ID entrustId, ETR_ENTRUST.ENTRUST_STATUS entrustStatus, ETR_ENTRUST.PORTFOLIO_ID portfolioId, PTL_PORTFOLIO.PORTFOLIO_NAME portfolioName,
ETR_ENTRUST_ADD.ASSET_TYPE1 assetType1, ETR_ENTRUST_ADD.ASSET_TYPE_10 assetType10, ETR_ENTRUST_ADD.ASSET_TYPE_11 assetType11,
FIN_PRODUCT.FINPROD_MARKET_ID finprodMarketId, FIN_PRODUCT.FINPROD_ID finprodId, FIN_PRODUCT.FINPROD_NAME finprodName, ETR_ENTRUST.PS ps, ETR_ENTRUST.PRICE*100 price, fc.PAY_CYCLE payFreq, ETR_ENTRUST.CCY ccy, ETR_ENTRUST.VDATE vdate, ETR_ENTRUST.MDATE mdate, ETR_ENTRUST.ENTRUST_AMT entrustAmt, ETR_FINISH_STATUS_A.FINISH_AMT finishAmt, round(ETR_FINISH_STATUS_A.FINISH_AMT/ETR_ENTRUST.ENTRUST_AMT,2)*100 transactioncom, su.REAL_NAME invManagerId, '' nextUser from ETR_ENTRUST
left join PTL_PORTFOLIO on PTL_PORTFOLIO.PORTFOLIO_ID = ETR_ENTRUST.PORTFOLIO_ID
inner join FIN_PRODUCT on FIN_PRODUCT.FINPROD_ID = ETR_ENTRUST.FINPROD_ID left join FIN_CASH_PAY_RULE fc on fc.FINPROD_ID = FIN_PRODUCT.FINPROD_ID
left join FIN_PRODUCT_TYPE on FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_TYPE.FINPROD_ID
inner join ETR_ENTRUST_ADD on ETR_ENTRUST_ADD.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID left join (select ENTRUST_ID,sum(FINISH_AMT) as FINISH_AMT from ETR_FINISH_STATUS group by ENTRUST_ID) ETR_FINISH_STATUS_A on ETR_FINISH_STATUS_A.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID left join sys_user su on ETR_ENTRUST.INV_MANAGER_ID=su.user_name INNER JOIN PTL_PORTFOLIO_AUTHORITY ON PTL_PORTFOLIO.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID AND PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userId}
PTL_PORTFOLIO.PORTFOLIO_TYPE IN (#{portfolioType}, #{portfolioType1})
AND (PTL_PORTFOLIO.PORTFOLIO_ID IN
null) OR PTL_PORTFOLIO.PORTFOLIO_ID IN (
#{prot}
or PTL_PORTFOLIO.PARENT_PORTFOLIO_ID IN
null) OR PTL_PORTFOLIO.PORTFOLIO_ID IN (
#{prot}
)
AND ETR_ENTRUST_ADD.ASSET_TYPE1 IN
#{item,jdbcType=VARCHAR}
AND ETR_ENTRUST.CCY = #{ccy,jdbcType=VARCHAR}
AND ETR_ENTRUST.PS = #{ps,jdbcType=VARCHAR}
AND ETR_ENTRUST.ENTRUST_STATUS = #{entrustStatus,jdbcType=VARCHAR}
AND ETR_ENTRUST.VDATE >= #{startDate,jdbcType=DATE}
AND ETR_ENTRUST.MDATE <= #{endDate,jdbcType=DATE}
AND (FIN_PRODUCT.FINPROD_MARKET_ID like concat('%',concat(#{finprodId,jdbcType=VARCHAR},'%')) OR FIN_PRODUCT.FINPROD_NAME like concat('%',concat(#{finprodId,jdbcType=VARCHAR},'%')) )
AND FIN_PRODUCT.FINPROD_TYPE2 = #{finprodType2,jdbcType=VARCHAR}
AND FIN_PRODUCT_TYPE.TYPE_9 in
#{item}
AND FIN_PRODUCT_TYPE.TYPE_10 in
#{item}
AND FIN_PRODUCT_TYPE.TYPE_11 in
#{item}

select ETR_ENTRUST.ENTRUST_ID entrustId, '08' entrustStatus, ETR_ENTRUST.PORTFOLIO_ID portfolioId, PTL_PORTFOLIO.PORTFOLIO_NAME portfolioName,
ETR_ENTRUST_ADD.ASSET_TYPE1 assetType1, ETR_ENTRUST_ADD.ASSET_TYPE_10 assetType10, ETR_ENTRUST_ADD.ASSET_TYPE_11 assetType11,
FIN_PRODUCT.FINPROD_MARKET_ID finprodMarketId, FIN_PRODUCT.FINPROD_ID finprodId, FIN_PRODUCT.FINPROD_NAME finprodName, ETR_ENTRUST.PS ps, ETR_ENTRUST.PRICE*100 price, fc.PAY_CYCLE payFreq, ETR_ENTRUST.CCY ccy, ETR_ENTRUST.VDATE vdate, ETR_ENTRUST.MDATE mdate, ETR_ENTRUST.ENTRUST_AMT entrustAmt, ETR_FINISH_STATUS_A.FINISH_AMT finishAmt, round(ETR_FINISH_STATUS_A.FINISH_AMT/ETR_ENTRUST.ENTRUST_AMT,2)*100 transactioncom, su.REAL_NAME invManagerId, SWBL.NEXT_USER nextUser from WFL_ETR_ENTRUST ETR_ENTRUST
left join PTL_PORTFOLIO on PTL_PORTFOLIO.PORTFOLIO_ID = ETR_ENTRUST.PORTFOLIO_ID
inner join FIN_PRODUCT on FIN_PRODUCT.FINPROD_ID = ETR_ENTRUST.FINPROD_ID left join FIN_CASH_PAY_RULE fc on fc.FINPROD_ID = FIN_PRODUCT.FINPROD_ID
left join FIN_PRODUCT_TYPE on FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_TYPE.FINPROD_ID
inner join WFL_ETR_ENTRUST_ADD ETR_ENTRUST_ADD on ETR_ENTRUST_ADD.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID left join (select ENTRUST_ID,sum(FINISH_AMT) as FINISH_AMT from ETR_FINISH_STATUS group by ENTRUST_ID) ETR_FINISH_STATUS_A on ETR_FINISH_STATUS_A.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID left join sys_user su on ETR_ENTRUST.INV_MANAGER_ID=su.user_name INNER JOIN PTL_PORTFOLIO_AUTHORITY ON PTL_PORTFOLIO.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID AND PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userId} LEFT JOIN SYS_WFL_BUSINESS_LIST SWBL ON SWBL.SEQ_NO = ETR_ENTRUST.WORKFLOW_ID and SWBL.PROCESS_STATE != 'END'
PTL_PORTFOLIO.PORTFOLIO_TYPE IN (#{portfolioType}, #{portfolioType1})
AND (PTL_PORTFOLIO.PORTFOLIO_ID IN
null) OR PTL_PORTFOLIO.PORTFOLIO_ID IN (
#{prot}
or PTL_PORTFOLIO.PARENT_PORTFOLIO_ID IN
null) OR PTL_PORTFOLIO.PORTFOLIO_ID IN (
#{prot}
)
AND ETR_ENTRUST_ADD.ASSET_TYPE1 IN
#{item,jdbcType=VARCHAR}
AND ETR_ENTRUST.CCY = #{ccy,jdbcType=VARCHAR}
AND ETR_ENTRUST.PS = #{ps,jdbcType=VARCHAR}
AND ETR_ENTRUST.VDATE >= #{startDate,jdbcType=DATE}
AND ETR_ENTRUST.MDATE <= #{endDate,jdbcType=DATE}
AND (FIN_PRODUCT.FINPROD_MARKET_ID like concat('%',concat(#{finprodId,jdbcType=VARCHAR},'%')) OR FIN_PRODUCT.FINPROD_NAME like concat('%',concat(#{finprodId,jdbcType=VARCHAR},'%')) )
AND FIN_PRODUCT.FINPROD_TYPE2 = #{finprodType2,jdbcType=VARCHAR}
AND FIN_PRODUCT_TYPE.TYPE_9 in
#{item}
AND FIN_PRODUCT_TYPE.TYPE_10 in
