mapper.select:
SELECT PTL_PORTFOLIO.PORTFOLIO_ID code, PTL_PORTFOLIO.PORTFOLIO_NAME name, PTL_PORTFOLIO.PORTFOLIO_NAME shortName， PTL_PORTFOLIO.PORTFOLIO_ID hidCode FROM PTL_PORTFOLIO INNER JOIN PTL_PORTFOLIO_AUTHORITY ON PTL_PORTFOLIO.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID AND PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userId}
PTL_PORTFOLIO.PORTFOLIO_ID like concat('%',concat(#{portfolioId,jdbcType=VARCHAR},'%')) OR PTL_PORTFOLIO.PORTFOLIO_NAME like concat('%',concat(#{portfolioId,jdbcType=VARCHAR},'%'))
AND T1.PORTFOLIO_TYPE IN (#{portType}, #{portType1})

SELECT FINPROD_MARKET_ID code, FINPROD_ABBR name, FINPROD_ABBR shortName, FINPROD_ID finprodId FROM FIN_PRODUCT
FINPROD_MARKET_ID like concat('%',concat(#{finprodId,jdbcType=VARCHAR},'%'))
AND FIN_PRODUCT.FINPROD_TYPE2 = #{finprodType2,jdbcType=VARCHAR}

select FIN_PRODUCT.FINPROD_MARKET_ID id, FIN_PRODUCT.FINPROD_NAME text, NVL(FIN_PRODUCT.FINPROD_ABBR, FIN_PRODUCT.FINPROD_NAME) FINPROD_NAME, FIN_PRODUCT.FINPROD_ID, FIN_PRODUCT.VDATE, FIN_PRODUCT.MDATE, FIN_PRODUCT.TERM_DAYS, FIN_PRODUCT.CCY, FIN_CASH_CALC_RULE.YIELD*100 YIELD, FIN_PRODUCT_TYPE.TYPE_6,
FIN_PRODUCT_TYPE.TYPE_9, FIN_PRODUCT_TYPE.TYPE_10, FIN_PRODUCT_TYPE.TYPE_11,
FIN_PRODUCT.ISSUE_AMT, mcp.counter_id ISSUER from FIN_PRODUCT left join FIN_CASH_CALC_RULE on FIN_PRODUCT.FINPROD_ID = FIN_CASH_CALC_RULE.FINPROD_ID and FIN_PRODUCT.VDATE = FIN_CASH_CALC_RULE.EFF_DATE left join FIN_CASH_INFO on FIN_CASH_CALC_RULE.CASH_ID = FIN_CASH_INFO.CASH_ID left join FIN_PRODUCT_TYPE on FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_TYPE.FINPROD_ID left join mst_counter_party mcp on mcp.link_id = FIN_PRODUCT.ISSUER
FIN_PRODUCT.FINPROD_MARKET_ID =#{initValue,jdbcType=VARCHAR}
AND (FIN_PRODUCT.FINPROD_MARKET_ID like concat('%',concat(#{search,jdbcType=VARCHAR},'%')) OR FIN_PRODUCT.FINPROD_NAME like concat('%',concat(#{search,jdbcType=VARCHAR},'%')) )
AND FIN_PRODUCT.FINPROD_TYPE2 = #{finprodType2, jdbcType=VARCHAR}
AND FIN_CASH_INFO.CASH_TYPE_1 = #{cashType1, jdbcType=VARCHAR}

select PTL_PORTFOLIO.PORTFOLIO_ID id, PTL_PORTFOLIO.PORTFOLIO_NAME text from PTL_PORTFOLIO inner join PTL_PORTFOLIO_AUTHORITY on PTL_PORTFOLIO.PORTFOLIO_ID=PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID
AND (PTL_PORTFOLIO.PORTFOLIO_ID like concat('%',concat(#{search,jdbcType=VARCHAR},'%')) OR PTL_PORTFOLIO.PORTFOLIO_NAME like concat('%',concat(#{search,jdbcType=VARCHAR},'%')))
AND PTL_PORTFOLIO.PORTFOLIO_ID = #{initValue,jdbcType=VARCHAR}
AND PTL_PORTFOLIO.PORTFOLIO_TYPE in
#{portType}
and PTL_PORTFOLIO_AUTHORITY.USER_ID= #{loginUser}

select pcp.amount
  from ptl_cash_position pcp
 where pcp.portfolio_id = #{portfolio_id ,jdbcType=VARCHAR}
   and pcp.chl_finprod_id = #{chl_finprod_id ,jdbcType=VARCHAR}
   and pcp.cdate = #{platDate,jdbcType=DATE}
   and pcp.hoding_type = '03'

select sum(nvl(ENTRUST_AMT,0)) ENTRUST_AMT
from  ETR_ENTRUST
where FINPROD_ID = #{finprodId,jdbcType=VARCHAR} and PS = #{ps,jdbcType=VARCHAR}
and ENTRUST_STATUS in

    #{item,jdbcType=VARCHAR}

group by  FINPROD_ID
